function createStrategy() {
  const costs = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  const preferred = [4, 8, 12, 6, 10, 11, 7, 13, 5, 14, 9, 2, 3, 1, 0, 15];
  return {
    plan(s) {
      const a = [];
      let gold = s.gold;
      const owned = new Set();
      for (const sl of s.slots) if (sl.turret) owned.add(sl.slot);
