        }
        return false;
      }
      if (s.wave === 1) {
        build(4, "bolt"); build(8, "bolt"); build(12, "bolt"); build(6, "cannon");
      }
      if (s.wave === 2) build(10, "frost");
      if (s.wave === 3) build(11, "flak");
      for (const slot of preferred) {
        const t = s.slots[slot].turret;
